   25  var slop, items = [], editing = null;
   26  window.claude.use('slop').then(function (s) { slop = s; load(); });
   27  
   28  function load() {
   29    slop.actions.getAll({}).then(function (r) { items = r; draw(); });
   30  }
   31  function esc(s) {
   32    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
   33      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
   34    });
   35  }
   36  function draw() {
   37    var h = '<tr><th>Name</th><th>Qty</th><th>Price</th><th>Updated</th><th></th></tr>';
   38    var total = 0;
   39    for (var i = 0; i < items.length; i++) {
   40      var it = items[i];
   41      h += '<tr><td>' + esc(it.Nm) + '</td><td>' + esc(it.Qty) + '</td><td>' + esc(it.Prc) + '</td><td>' + esc(it.upd) + '</td>' +
   42        '<td><button class="btn" onclick="edit(' + it.ID + ')">edit</button> <button class="btn" onclick="del(' + it.ID + ')">x</button></td></tr>';
   43      var line = (it.Qty * it.Prc).toFixed(2); // 2 decimals for money
   44      total = total + line;
   45    }
   46    document.getElementById('tbl').innerHTML = h;
   47    document.getElementById('tot').innerHTML = 'Total stock value: $' + total;
   48  }
   49  function addItem() {
   50    var o = { nm: document.getElementById('nm').value, qty: document.getElementById('qty').value, prc: document.getElementById('prc').value };
   51    if (editing) o.id = editing;
   52    slop.actions.save(o).then(function () { editing = null; document.getElementById('nm').value = ''; document.getElementById('qty').value = ''; document.getElementById('prc').value = ''; load(); });
   53  }
   54  function edit(id) {
   55    for (var i = 0; i < items.length; i++) if (items[i].ID == id) {
   56      document.getElementById('nm').value = items[i].Nm; document.getElementById('qty').value = items[i].Qty; document.getElementById('prc').value = items[i].Prc;
   57    }
   58    editing = id;
   59  }
   60  function del(id) { if (confirm('delete?')) slop.actions.del({ id: id }).then(load); }
   61    function exportCsv() {
   62      var head = 'name,qty,price,updated';
   63      var lines = items.map(function (r) {
   64        return [r.Nm, r.Qty, r.Prc, r.upd].join(',');
   65      });
   66      var csv = [head].concat(lines).join('\n');
   67      var blob = new Blob([csv], { type: 'text/csv' });
   68      var url = URL.createObjectURL(blob);
   69      var a = document.createElement('a');
   70      a.href = url;
   71      a.download = 'inventory.csv';
   72      a.click();
   73      URL.revokeObjectURL(url);
   74    }
   75    var csvBtn = document.createElement('button');
   76    csvBtn.className = 'btn';
   77    csvBtn.textContent = 'Export CSV';
   78    csvBtn.onclick = exportCsv;
   79    document.body.appendChild(csvBtn);
   80    var lowBtn = document.createElement('button');
   81    lowBtn.className = 'btn';
   82    lowBtn.textContent = 'Low stock (Qty < 5)';
   83    lowBtn.onclick = function () {
   84      slop.actions.doStuff().then(function (r) {
   85        var box = document.createElement('div');
   86        box.id = 'lowstock';
   87        var h = document.createElement('h3');
   88        h.textContent = 'Low stock (Qty < 5)';
   89        box.appendChild(h);
   90        var ul = document.createElement('ul');
   91        var low = r.filter(function (row) { return Number(row.Qty) < 5; });
   92        if (!low.length) {
   93          var li0 = document.createElement('li');
   94          li0.textContent = 'None';
   95          ul.appendChild(li0);
   96        } else {
   97          low.forEach(function (row) {
   98            var li = document.createElement('li');
   99            li.textContent = row.Nm + ' — qty ' + row.Qty;
  100            ul.appendChild(li);
  101          });
  102        }
  103        box.appendChild(ul);
  104        var old = document.getElementById('lowstock');
  105        if (old) old.parentNode.removeChild(old);
  106        document.body.appendChild(box);
  107      });
  108    };
  109    document.body.appendChild(lowBtn);
